/*
 * Fast dominant eigenpair for small real square matrices (n <= 32).
 *
 * Algorithm:
 *   1. Householder reduction to upper Hessenberg form (real).
 *   2. Complex single-shift (Wilkinson) explicit QR iteration with Givens
 *      rotations + deflation to obtain all eigenvalues.
 *   3. Pick eigenvalue of largest magnitude.
 *   4. Inverse iteration with complex LU (partial pivoting, perturbed tiny
 *      pivots) on (A - lambda*I) for the eigenvector.
 *   5. Residual check; on any failure return Py_None so the Python caller
 *      can fall back to numpy.linalg.eig.
 */
#define PY_SSIZE_T_CLEAN
#include <Python.h>
#define NPY_NO_DEPRECATED_API NPY_1_7_API_VERSION
#include <numpy/arrayobject.h>

#include <complex.h>
#include <float.h>
#include <math.h>

#define MAXN 32
typedef double complex cdbl;

static const double EPS = 2.220446049250313e-16;

/* --- Householder reduction of a (row-major, lda=n) to upper Hessenberg --- */
static void
hessenberg(double *a, int n)
{
    double v[MAXN];
    int k, i, j;

    for (k = 0; k + 2 < n; k++) {
        double nrm = 0.0, alpha, vnrm2, s;
        for (i = k + 1; i < n; i++) {
            double t = a[i * n + k];
            v[i] = t;
            nrm += t * t;
        }
        nrm = sqrt(nrm);
        if (nrm == 0.0) {
            continue;
        }
        alpha = (v[k + 1] >= 0.0) ? -nrm : nrm;
        v[k + 1] -= alpha;
        vnrm2 = 0.0;
        for (i = k + 1; i < n; i++) {
            vnrm2 += v[i] * v[i];
        }
        if (vnrm2 <= 0.0) {
            continue;
        }
        /* A <- (I - 2 v v^T / v^T v) A   (rows k+1..n-1) */
        for (j = k; j < n; j++) {
            s = 0.0;
            for (i = k + 1; i < n; i++) {
                s += v[i] * a[i * n + j];
            }
            s = 2.0 * s / vnrm2;
            for (i = k + 1; i < n; i++) {
                a[i * n + j] -= s * v[i];
            }
        }
        /* A <- A (I - 2 v v^T / v^T v)   (cols k+1..n-1) */
        for (i = 0; i < n; i++) {
            s = 0.0;
            for (j = k + 1; j < n; j++) {
                s += a[i * n + j] * v[j];
            }
            s = 2.0 * s / vnrm2;
            for (j = k + 1; j < n; j++) {
                a[i * n + j] -= s * v[j];
            }
        }
        for (i = k + 2; i < n; i++) {
            a[i * n + k] = 0.0;
        }
        a[k + 1] = a[k + 1]; /* no-op, keeps compilers quiet */
    }
}

/* eigenvalues of [[a,b],[c,d]] */
static void
eig2(cdbl a, cdbl b, cdbl c, cdbl d, cdbl *l1, cdbl *l2)
{
    cdbl tr = a + d;
    cdbl det = a * d - b * c;
    cdbl disc = csqrt(tr * tr / 4.0 - det);
    cdbl h = tr / 2.0;
    *l1 = h + disc;
    *l2 = h - disc;
}

/*
 * Complex QR iteration on Hessenberg matrix h (row-major, lda=n).
 * Eigenvalues written to w. Returns 0 on success, -1 if not converged.
 */
static int
qr_eigenvalues(cdbl *h, int n, cdbl *w)
{
    int hi = n - 1;
    int total = 0;
    int since_deflate = 0;

    while (hi >= 0) {
        int lo, l, i, j;

        if (hi == 0) {
            w[0] = h[0];
            break;
        }
        /* find start of the unreduced block ending at hi */
        lo = 0;
        for (l = hi; l >= 1; l--) {
            double sub = cabs(h[l * n + l - 1]);
            double dsum = cabs(h[l * n + l]) + cabs(h[(l - 1) * n + l - 1]);
            if (dsum == 0.0) {
                dsum = 1.0;
            }
            if (sub <= EPS * dsum) {
                h[l * n + l - 1] = 0.0;
                lo = l;
                break;
            }
        }
        if (lo == hi) {
            w[hi] = h[hi * n + hi];
            hi -= 1;
            since_deflate = 0;
            continue;
        }
        if (lo == hi - 1) {
            cdbl l1, l2;
            eig2(h[lo * n + lo], h[lo * n + hi], h[hi * n + lo],
                 h[hi * n + hi], &l1, &l2);
            w[hi] = l1;
            w[hi - 1] = l2;
            hi -= 2;
            since_deflate = 0;
            continue;
        }

        if (++total > 60 * n + 200) {
            return -1;
        }
        since_deflate++;

        {
            cdbl sigma, cs[MAXN], sn[MAXN];
            if (since_deflate % 11 == 10) {
                /* exceptional shift */
                sigma = h[hi * n + hi] + cabs(h[hi * n + hi - 1])
                        + cabs(h[(hi - 1) * n + hi - 2]);
            }
            else {
                cdbl l1, l2, d = h[hi * n + hi];
                eig2(h[(hi - 1) * n + hi - 1], h[(hi - 1) * n + hi],
                     h[hi * n + hi - 1], d, &l1, &l2);
                sigma = (cabs(l1 - d) <= cabs(l2 - d)) ? l1 : l2;
            }
            for (i = lo; i <= hi; i++) {
                h[i * n + i] -= sigma;
            }
            /* QR factorisation of the block via Givens rotations */
            for (i = lo; i < hi; i++) {
                cdbl a = h[i * n + i], b = h[(i + 1) * n + i], c, s;
                double r = sqrt(creal(a) * creal(a) + cimag(a) * cimag(a)
                                + creal(b) * creal(b) + cimag(b) * cimag(b));
                if (r == 0.0) {
                    c = 1.0;
                    s = 0.0;
                }
                else {
                    c = conj(a) / r;
                    s = conj(b) / r;
                }
                cs[i] = c;
                sn[i] = s;
                for (j = i; j <= hi; j++) {
                    cdbl x = h[i * n + j], y = h[(i + 1) * n + j];
                    h[i * n + j] = c * x + s * y;
                    h[(i + 1) * n + j] = -conj(s) * x + conj(c) * y;
                }
            }
            /* R * Q^H : column updates */
            for (i = lo; i < hi; i++) {
                cdbl c = cs[i], s = sn[i];
                int rmax = (i + 2 <= hi) ? i + 2 : hi;
                for (j = lo; j <= rmax; j++) {
                    cdbl x = h[j * n + i], y = h[j * n + i + 1];
                    h[j * n + i] = conj(c) * x + conj(s) * y;
                    h[j * n + i + 1] = -s * x + c * y;
                }
            }
            for (i = lo; i <= hi; i++) {
                h[i * n + i] += sigma;
            }
        }
    }
    return 0;
}

/*
 * Inverse iteration: eigenvector of A (real, row-major) for eigenvalue lam.
 * Writes unit-2-norm vector to x. Returns 0 on success, -1 on failure.
 */
static int
inverse_iteration(const double *a, int n, cdbl lam, double anorm, cdbl *x)
{
    cdbl m[MAXN * MAXN];
    int piv[MAXN];
    double tiny;
    int i, j, k, it;

    tiny = EPS * ((anorm > 1.0) ? anorm : 1.0);
    if (!(tiny > 0.0)) {
        tiny = EPS;
    }

    for (i = 0; i < n; i++) {
        for (j = 0; j < n; j++) {
            m[i * n + j] = a[i * n + j];
        }
        m[i * n + i] -= lam;
    }

    /* LU with partial pivoting, singular pivots perturbed */
    for (k = 0; k < n; k++) {
        int p = k;
        double best = cabs(m[k * n + k]);
        for (i = k + 1; i < n; i++) {
            double v = cabs(m[i * n + k]);
            if (v > best) {
                best = v;
                p = i;
            }
        }
        piv[k] = p;
        if (p != k) {
            for (j = 0; j < n; j++) {
                cdbl t = m[k * n + j];
                m[k * n + j] = m[p * n + j];
                m[p * n + j] = t;
            }
        }
        if (cabs(m[k * n + k]) < tiny) {
            m[k * n + k] = tiny;
        }
        for (i = k + 1; i < n; i++) {
            cdbl f = m[i * n + k] / m[k * n + k];
            m[i * n + k] = f;
            if (f != 0.0) {
                for (j = k + 1; j < n; j++) {
                    m[i * n + j] -= f * m[k * n + j];
                }
            }
        }
    }

    for (i = 0; i < n; i++) {
        x[i] = 1.0 / sqrt((double)n);
    }

    for (it = 0; it < 2; it++) {
        cdbl b[MAXN];
        double nrm = 0.0;
        for (i = 0; i < n; i++) {
            b[i] = x[i];
        }
        /* apply row permutation */
        for (k = 0; k < n; k++) {
            int p = piv[k];
            if (p != k) {
                cdbl t = b[k];
                b[k] = b[p];
                b[p] = t;
            }
        }
        /* forward substitution (unit lower triangular) */
        for (i = 1; i < n; i++) {
            cdbl s = b[i];
            for (j = 0; j < i; j++) {
                s -= m[i * n + j] * b[j];
            }
            b[i] = s;
        }
        /* back substitution */
        for (i = n - 1; i >= 0; i--) {
            cdbl s = b[i];
            for (j = i + 1; j < n; j++) {
                s -= m[i * n + j] * b[j];
            }
            b[i] = s / m[i * n + i];
        }
        for (i = 0; i < n; i++) {
            double re = creal(b[i]), im = cimag(b[i]);
            if (!isfinite(re) || !isfinite(im)) {
                return -1;
            }
            nrm += re * re + im * im;
        }
        nrm = sqrt(nrm);
        if (!(nrm > 0.0) || !isfinite(nrm)) {
            return -1;
        }
        for (i = 0; i < n; i++) {
            x[i] = b[i] / nrm;
        }
    }
    return 0;
}

static PyObject *
dominant_eig(PyObject *self, PyObject *arg)
{
    PyArrayObject *arr;
    double a[MAXN * MAXN];
    cdbl h[MAXN * MAXN];
    cdbl w[MAXN], x[MAXN], ax[MAXN];
    cdbl lam, lam_r;
    double anorm = 0.0, best;
    npy_intp dims[1];
    const double *src;
    int n, i, j, k;

    arr = (PyArrayObject *)PyArray_FROM_OTF(arg, NPY_DOUBLE,
                                            NPY_ARRAY_IN_ARRAY);
    if (arr == NULL) {
        PyErr_Clear();
        Py_RETURN_NONE;
    }
    if (PyArray_NDIM(arr) != 2 || PyArray_DIM(arr, 0) != PyArray_DIM(arr, 1)
        || PyArray_DIM(arr, 0) < 1 || PyArray_DIM(arr, 0) > MAXN) {
        Py_DECREF(arr);
        Py_RETURN_NONE;
    }
    n = (int)PyArray_DIM(arr, 0);
    src = (const double *)PyArray_DATA(arr);
    for (i = 0; i < n * n; i++) {
        double v = src[i];
        if (!isfinite(v)) {
            Py_DECREF(arr);
            Py_RETURN_NONE;
        }
        a[i] = v;
        anorm += v * v;
    }
    Py_DECREF(arr);
    anorm = sqrt(anorm);

    if (n == 1) {
        lam = a[0];
        x[0] = 1.0;
    }
    else {
        if (n == 2) {
            cdbl l1, l2;
            eig2(a[0], a[1], a[2], a[3], &l1, &l2);
            w[0] = l1;
            w[1] = l2;
        }
        else {
            for (i = 0; i < n * n; i++) {
                h[i] = a[i];
            }
            hessenberg((double *)NULL, 0); /* placeholder, replaced below */
            {
                double hr[MAXN * MAXN];
                for (i = 0; i < n * n; i++) {
                    hr[i] = a[i];
                }
                hessenberg(hr, n);
                for (i = 0; i < n; i++) {
                    for (j = 0; j < n; j++) {
                        h[i * n + j] = (j + 1 >= i) ? hr[i * n + j] : 0.0;
                    }
                }
            }
            if (qr_eigenvalues(h, n, w) != 0) {
                Py_RETURN_NONE;
            }
        }
        k = 0;
        best = -1.0;
        for (i = 0; i < n; i++) {
            double m = cabs(w[i]);
            if (!isfinite(m)) {
                Py_RETURN_NONE;
            }
            if (m > best) {
                best = m;
                k = i;
            }
        }
        lam = w[k];
        if (inverse_iteration(a, n, lam, anorm, x) != 0) {
            Py_RETURN_NONE;
        }
    }

    /* A x, Rayleigh quotient, residual selection */
    {
        cdbl num = 0.0;
        double res1 = 0.0, res2 = 0.0, scale;
        for (i = 0; i < n; i++) {
            cdbl s = 0.0;
            for (j = 0; j < n; j++) {
                s += a[i * n + j] * x[j];
            }
            ax[i] = s;
            num += conj(x[i]) * s;
        }
        lam_r = num; /* x has unit 2-norm */
        for (i = 0; i < n; i++) {
            cdbl d1 = ax[i] - lam * x[i];
            cdbl d2 = ax[i] - lam_r * x[i];
            res1 += creal(d1) * creal(d1) + cimag(d1) * cimag(d1);
            res2 += creal(d2) * creal(d2) + cimag(d2) * cimag(d2);
        }
        if (res2 < res1) {
            lam = lam_r;
            res1 = res2;
        }
        res1 = sqrt(res1);
        scale = cabs(lam);
        if (scale < anorm) {
            scale = anorm;
        }
        if (scale < 1.0) {
            scale = 1.0;
        }
        if (!isfinite(res1) || res1 > 1e-9 * scale) {
            Py_RETURN_NONE;
        }
    }

    dims[0] = n;
    {
        PyObject *vec, *val, *tup;
        cdbl *out;
        vec = PyArray_SimpleNew(1, dims, NPY_COMPLEX128);
        if (vec == NULL) {
            return NULL;
        }
        out = (cdbl *)PyArray_DATA((PyArrayObject *)vec);
        for (i = 0; i < n; i++) {
            out[i] = x[i];
        }
        {
            npy_complex128 cval;
            PyArray_Descr *descr;
            double re = creal(lam), im = cimag(lam);
            memcpy(&cval, &re, sizeof(double));
            memcpy(((char *)&cval) + sizeof(double), &im, sizeof(double));
            descr = PyArray_DescrFromType(NPY_COMPLEX128);
            if (descr == NULL) {
                Py_DECREF(vec);
                return NULL;
            }
            val = PyArray_Scalar(&cval, descr, NULL);
            Py_DECREF(descr);
        }
        if (val == NULL) {
            Py_DECREF(vec);
            return NULL;
        }
        tup = PyTuple_New(2);
        if (tup == NULL) {
            Py_DECREF(vec);
            Py_DECREF(val);
            return NULL;
        }
        PyTuple_SET_ITEM(tup, 0, val);
        PyTuple_SET_ITEM(tup, 1, vec);
        return tup;
    }
}

static PyMethodDef methods[] = {
    {"dominant_eig", dominant_eig, METH_O,
     "Dominant eigenvalue/eigenvector of a small real square matrix."},
    {NULL, NULL, 0, NULL}};

static struct PyModuleDef moduledef = {PyModuleDef_HEAD_INIT, "_eigenfast",
                                       NULL, -1, methods, NULL, NULL, NULL,
                                       NULL};

PyMODINIT_FUNC
PyInit__eigenfast(void)
{
    import_array();
    return PyModule_Create(&moduledef);
}

/*
 * Fast dominant eigenpair for small real square matrices (n <= 32).
 *
 * Algorithm:
 *   1. Householder reduction to upper Hessenberg form (real).
 *   2. Complex single-shift (Wilkinson) explicit QR iteration with Givens
 *      rotations + deflation to obtain all eigenvalues.
 *   3. Pick eigenvalue of largest magnitude.
 *   4. Inverse iteration with complex LU (partial pivoting, perturbed tiny
 *      pivots) on (A - lambda*I) for the eigenvector.
 *   5. Residual check; on any failure return Py_None so the Python caller
 *      can fall back to numpy.linalg.eig.
 */
#define PY_SSIZE_T_CLEAN
#include <Python.h>
#define NPY_NO_DEPRECATED_API NPY_1_7_API_VERSION
#include <numpy/arrayobject.h>

#include <complex.h>
#include <float.h>
#include <math.h>

#define MAXN 32
typedef double complex cdbl;

static const double EPS = 2.220446049250313e-16;

/* --- Householder reduction of a (row-major, lda=n) to upper Hessenberg --- */
static void
hessenberg(double *a, int n)
{
    double v[MAXN];
    int k, i, j;

    for (k = 0; k + 2 < n; k++) {
        double nrm = 0.0, alpha, vnrm2, s;
        for (i = k + 1; i < n; i++) {
            double t = a[i * n + k];
            v[i] = t;
            nrm += t * t;
        }
        nrm = sqrt(nrm);
        if (nrm == 0.0) {
            continue;
        }
        alpha = (v[k + 1] >= 0.0) ? -nrm : nrm;
        v[k + 1] -= alpha;
        vnrm2 = 0.0;
        for (i = k + 1; i < n; i++) {
            vnrm2 += v[i] * v[i];
        }
        if (vnrm2 <= 0.0) {
            continue;
        }
        /* A <- (I - 2 v v^T / v^T v) A   (rows k+1..n-1) */
        for (j = k; j < n; j++) {
            s = 0.0;
            for (i = k + 1; i < n; i++) {
                s += v[i] * a[i * n + j];
            }
            s = 2.0 * s / vnrm2;
            for (i = k + 1; i < n; i++) {
                a[i * n + j] -= s * v[i];
            }
        }
        /* A <- A (I - 2 v v^T / v^T v)   (cols k+1..n-1) */
        for (i = 0; i < n; i++) {
            s = 0.0;
            for (j = k + 1; j < n; j++) {
                s += a[i * n + j] * v[j];
            }
            s = 2.0 * s / vnrm2;
            for (j = k + 1; j < n; j++) {
                a[i * n + j] -= s * v[j];
            }
        }
        for (i = k + 2; i < n; i++) {
            a[i * n + k] = 0.0;
        }
        a[k + 1] = a[k + 1]; /* no-op, keeps compilers quiet */
    }
}

/* eigenvalues of [[a,b],[c,d]] */
static void
eig2(cdbl a, cdbl b, cdbl c, cdbl d, cdbl *l1, cdbl *l2)
{
    cdbl tr = a + d;
    cdbl det = a * d - b * c;
    cdbl disc = csqrt(tr * tr / 4.0 - det);
    cdbl h = tr / 2.0;
    *l1 = h + disc;
    *l2 = h - disc;
}

/*
 * Complex QR iteration on Hessenberg matrix h (row-major, lda=n).
 * Eigenvalues written to w. Returns 0 on success, -1 if not converged.
 */
static int
qr_eigenvalues(cdbl *h, int n, cdbl *w)
{
    int hi = n - 1;
    int total = 0;
    int since_deflate = 0;

    while (hi >= 0) {
        int lo, l, i, j;

        if (hi == 0) {
            w[0] = h[0];
            break;
        }
        /* find start of the unreduced block ending at hi */
        lo = 0;
        for (l = hi; l >= 1; l--) {
            double sub = cabs(h[l * n + l - 1]);
            double dsum = cabs(h[l * n + l]) + cabs(h[(l - 1) * n + l - 1]);
            if (dsum == 0.0) {
                dsum = 1.0;
            }
            if (sub <= EPS * dsum) {
                h[l * n + l - 1] = 0.0;
                lo = l;
                break;
            }
        }
        if (lo == hi) {
            w[hi] = h[hi * n + hi];
            hi -= 1;
            since_deflate = 0;
            continue;
        }
        if (lo == hi - 1) {
            cdbl l1, l2;
            eig2(h[lo * n + lo], h[lo * n + hi], h[hi * n + lo],
                 h[hi * n + hi], &l1, &l2);
            w[hi] = l1;
            w[hi - 1] = l2;
            hi -= 2;
            since_deflate = 0;
            continue;
        }

        if (++total > 60 * n + 200) {
            return -1;
        }
        since_deflate++;

        {
            cdbl sigma, cs[MAXN], sn[MAXN];
            if (since_deflate % 11 == 10) {
                /* exceptional shift */
                sigma = h[hi * n + hi] + cabs(h[hi * n + hi - 1])
                        + cabs(h[(hi - 1) * n + hi - 2]);
            }
            else {
                cdbl l1, l2, d = h[hi * n + hi];
                eig2(h[(hi - 1) * n + hi - 1], h[(hi - 1) * n + hi],
                     h[hi * n + hi - 1], d, &l1, &l2);
                sigma = (cabs(l1 - d) <= cabs(l2 - d)) ? l1 : l2;
            }
            for (i = lo; i <= hi; i++) {
                h[i * n + i] -= sigma;
            }
            /* QR factorisation of the block via Givens rotations */
            for (i = lo; i < hi; i++) {
                cdbl a = h[i * n + i], b = h[(i + 1) * n + i], c, s;
                double r = sqrt(creal(a) * creal(a) + cimag(a) * cimag(a)
                                + creal(b) * creal(b) + cimag(b) * cimag(b));
                if (r == 0.0) {
                    c = 1.0;
                    s = 0.0;
                }
                else {
                    c = conj(a) / r;
                    s = conj(b) / r;
                }
                cs[i] = c;
                sn[i] = s;
                for (j = i; j <= hi; j++) {
                    cdbl x = h[i * n + j], y = h[(i + 1) * n + j];
