            for (i = lo; i < hi; i++) {
                cdbl c = cs[i], s = sn[i];
                int rmax = (i + 2 <= hi) ? i + 2 : hi;
                for (j = lo; j <= rmax; j++) {
                    cdbl x = h[j * n + i], y = h[j * n + i + 1];
                    h[j * n + i] = conj(c) * x + conj(s) * y;
                    h[j * n + i + 1] = -s * x + c * y;
                }
            }
            for (i = lo; i <= hi; i++) {
                h[i * n + i] += sigma;
