/*
 * Inverse iteration: eigenvector of A (real, row-major) for eigenvalue lam.
 * Writes unit-2-norm vector to x. Returns 0 on success, -1 on failure.
 */
static int
inverse_iteration(const double *a, int n, cdbl lam, double anorm, cdbl *x)
{
    cdbl m[MAXN * MAXN];
    int piv[MAXN];
    double tiny;
    int i, j, k, it;

    tiny = EPS * ((anorm > 1.0) ? anorm : 1.0);
    if (!(tiny > 0.0)) {
        tiny = EPS;
    }

    for (i = 0; i < n; i++) {
        for (j = 0; j < n; j++) {
            m[i * n + j] = a[i * n + j];
        }
        m[i * n + i] -= lam;
    }

    /* LU with partial pivoting, singular pivots perturbed */
    for (k = 0; k < n; k++) {
        int p = k;
        double best = cabs(m[k * n + k]);
        for (i = k + 1; i < n; i++) {
            double v = cabs(m[i * n + k]);
            if (v > best) {
                best = v;
                p = i;
            }
        }
        piv[k] = p;
        if (p != k) {
            for (j = 0; j < n; j++) {
                cdbl t = m[k * n + j];
                m[k * n + j] = m[p * n + j];
                m[p * n + j] = t;
            }
        }
        if (cabs(m[k * n + k]) < tiny) {
            m[k * n + k] = tiny;
        }
        for (i = k + 1; i < n; i++) {
            cdbl f = m[i * n + k] / m[k * n + k];
            m[i * n + k] = f;
            if (f != 0.0) {
                for (j = k + 1; j < n; j++) {
                    m[i * n + j] -= f * m[k * n + j];
                }
            }
        }
    }

    for (i = 0; i < n; i++) {
        x[i] = 1.0 / sqrt((double)n);
    }

    for (it = 0; it < 2; it++) {
        cdbl b[MAXN];
        double nrm = 0.0;
        for (i = 0; i < n; i++) {
            b[i] = x[i];
        }
        /* apply row permutation */
        for (k = 0; k < n; k++) {
            int p = piv[k];
            if (p != k) {
                cdbl t = b[k];
                b[k] = b[p];
                b[p] = t;
            }
        }
        /* forward substitution (unit lower triangular) */
        for (i = 1; i < n; i++) {
            cdbl s = b[i];
            for (j = 0; j < i; j++) {
                s -= m[i * n + j] * b[j];
            }
            b[i] = s;
        }
        /* back substitution */
        for (i = n - 1; i >= 0; i--) {
            cdbl s = b[i];
            for (j = i + 1; j < n; j++) {
                s -= m[i * n + j] * b[j];
            }
            b[i] = s / m[i * n + i];
        }
        for (i = 0; i < n; i++) {
            double re = creal(b[i]), im = cimag(b[i]);
            if (!isfinite(re) || !isfinite(im)) {
                return -1;
            }
            nrm += re * re + im * im;
        }
        nrm = sqrt(nrm);
        if (!(nrm > 0.0) || !isfinite(nrm)) {
            return -1;
        }
        for (i = 0; i < n; i++) {
            x[i] = b[i] / nrm;
        }
    }
    return 0;
}

