/* eigenvalues of the real 2x2 [[a,b],[c,d]] */
static void
eig2r(double a, double b, double c, double d, cdbl *l1, cdbl *l2)
{
    double h = 0.5 * (a + d);
    double disc = (0.5 * (a - d)) * (0.5 * (a - d)) + b * c;
    if (disc >= 0.0) {
        double s = sqrt(disc);
        *l1 = h + s;
        *l2 = h - s;
    }
    else {
        double s = sqrt(-disc);
        *l1 = h + s * I;
        *l2 = h - s * I;
    }
}

/*
 * Francis double-shift QR iteration on a real upper Hessenberg matrix h
 * (row-major, lda=n).  Eigenvalues written to w.
 * Returns 0 on success, -1 if not converged.
 */
static int
qr_eigenvalues(double *h, int n, double anorm, cdbl *w)
{
    int hi = n - 1;
    int total = 0;
    int since_deflate = 0;
    double scale = (anorm > 0.0) ? anorm : 1.0;

    while (hi >= 0) {
        int lo, l, k;
        double tr, det, x, y, z;

        if (hi == 0) {
            w[0] = h[0];
            break;
        }
        /* find start of the unreduced block ending at hi */
        lo = 0;
        for (l = hi; l >= 1; l--) {
            double sub = fabs(h[l * n + l - 1]);
            double dsum = fabs(h[l * n + l]) + fabs(h[(l - 1) * n + l - 1]);
            if (dsum == 0.0) {
                dsum = scale;
            }
            if (sub <= EPS * dsum) {
                h[l * n + l - 1] = 0.0;
                lo = l;
                break;
            }
        }
        if (lo == hi) {
            w[hi] = h[hi * n + hi];
            hi -= 1;
            since_deflate = 0;
            continue;
        }
        if (lo == hi - 1) {
            cdbl l1, l2;
            eig2r(h[lo * n + lo], h[lo * n + hi], h[hi * n + lo],
                  h[hi * n + hi], &l1, &l2);
            w[hi] = l1;
            w[hi - 1] = l2;
            hi -= 2;
            since_deflate = 0;
            continue;
        }

        if (++total > 40 * n + 100) {
            return -1;
        }
        since_deflate++;

        if (since_deflate % 11 == 10) {
            /* exceptional shift */
            double s = fabs(h[hi * n + hi - 1])
                       + fabs(h[(hi - 1) * n + hi - 2]);
            double h11 = 0.75 * s + h[hi * n + hi];
            tr = 2.0 * h11;
            det = h11 * h11 + 0.4375 * s * s;
        }
        else {
            double p = h[(hi - 1) * n + hi - 1], q = h[(hi - 1) * n + hi];
            double r = h[hi * n + hi - 1], s = h[hi * n + hi];
            tr = p + s;
            det = p * s - q * r;
        }

        /* first column of (H - l1 I)(H - l2 I) restricted to 3 entries */
        {
            double a11 = h[lo * n + lo];
            double a12 = h[lo * n + lo + 1];
            double a21 = h[(lo + 1) * n + lo];
            double a22 = h[(lo + 1) * n + lo + 1];
            double a32 = h[(lo + 2) * n + lo + 1];
            x = a11 * a11 + a12 * a21 - tr * a11 + det;
            y = a21 * (a11 + a22 - tr);
            z = a32 * a21;
        }

        /* chase the bulge down the diagonal with 3x3 Householder reflectors */
        for (k = lo; k <= hi - 2; k++) {
            double v0, v1, v2, nrm, alpha, vv, beta, s;
            int j, i, jmin, imax;

            nrm = sqrt(x * x + y * y + z * z);
            if (nrm == 0.0) {
                x = h[(k + 1) * n + k];
                y = h[(k + 2) * n + k];
                z = (k + 3 <= hi) ? h[(k + 3) * n + k] : 0.0;
                continue;
