            alpha = (x >= 0.0) ? -nrm : nrm;
            v0 = x - alpha;
            v1 = y;
            v2 = z;
            vv = v0 * v0 + v1 * v1 + v2 * v2;
            if (vv == 0.0) {
                continue;
            }
            beta = 2.0 / vv;

            jmin = (k > lo) ? k - 1 : lo;
            for (j = jmin; j <= hi; j++) {
                s = beta
                    * (v0 * h[k * n + j] + v1 * h[(k + 1) * n + j]
                       + v2 * h[(k + 2) * n + j]);
                h[k * n + j] -= s * v0;
                h[(k + 1) * n + j] -= s * v1;
                h[(k + 2) * n + j] -= s * v2;
            }
            imax = (k + 3 <= hi) ? k + 3 : hi;
            for (i = lo; i <= imax; i++) {
                s = beta
                    * (v0 * h[i * n + k] + v1 * h[i * n + k + 1]
                       + v2 * h[i * n + k + 2]);
                h[i * n + k] -= s * v0;
                h[i * n + k + 1] -= s * v1;
                h[i * n + k + 2] -= s * v2;
            }
            if (k > lo) {
                h[(k + 1) * n + k - 1] = 0.0;
                h[(k + 2) * n + k - 1] = 0.0;
            }
            x = h[(k + 1) * n + k];
            y = h[(k + 2) * n + k];
            z = (k + 3 <= hi) ? h[(k + 3) * n + k] : 0.0;
        }

        /* final 2x2 reflector to restore Hessenberg form */
        {
            double v0, v1, nrm, alpha, vv, beta, s;
            int j, i, k2 = hi - 1;

            nrm = sqrt(x * x + y * y);
            if (nrm > 0.0) {
                alpha = (x >= 0.0) ? -nrm : nrm;
                v0 = x - alpha;
                v1 = y;
                vv = v0 * v0 + v1 * v1;
                if (vv > 0.0) {
                    beta = 2.0 / vv;
                    for (j = k2 - 1; j <= hi; j++) {
                        s = beta
                            * (v0 * h[k2 * n + j] + v1 * h[(k2 + 1) * n + j]);
                        h[k2 * n + j] -= s * v0;
                        h[(k2 + 1) * n + j] -= s * v1;
                    }
                    for (i = lo; i <= hi; i++) {
                        s = beta
                            * (v0 * h[i * n + k2] + v1 * h[i * n + k2 + 1]);
                        h[i * n + k2] -= s * v0;
                        h[i * n + k2 + 1] -= s * v1;
                    }
                    h[(k2 + 1) * n + k2 - 1] = 0.0;
                }
            }
        }
    }
    return 0;
}

